{
  "probability": 0.98,
  "range_low": 0.93,
  "range_high": 0.99,
  "summary": [
    "Based on IOM Missing Migrants data, about 606 deaths/missing by Feb 24, 2026, implying a high early-year pace that could reach 900 by end-March if it persists.",
    "March fatality pace, potential adverse weather, and continued risk keep the possibility plausible, though not certain.",
    "Improvements in SAR or policy actions could dampen fatalities; data revisions could push totals higher.",
    "Bayesian synthesis yields a calibrated posterior probability of 98% for reaching 900 by end of March."
  ],
  "confidence": "high",
  "narrative": "Starting from the IOM-based near-term anchor of 606 deaths by late February, and updating for March pace, weather risk, and SAR dynamics, the combined evidence makes crossing 900 by end-March very likely but not guaranteed. The calibrated posterior is 98% with a plausible 93–99% range, acknowledging volatility in data and policy responses.",
  "justification": {
    "anchor": {
      "probability": 0.95,
      "basis": "Reference class uses IOM Missing Migrants Project Central Mediterranean fatality counts; February 2026 data show 606 deaths/missing by Feb 24; this pace supports a high likelihood of reaching 900 by end-March if sustained."
    },
    "factor_updates": [
      {
        "factor": "Pace of fatalities in March 2026 along the Central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by Feb 24 imply a high early-year pace; continuing at roughly 8–11 fatalities per day in March could push total to or beyond 900 by end-March."
      },
      {
        "factor": "Severe weather/rough sea conditions in the central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Adverse conditions increase risk of capsizes and fatalities, raising the odds of additional deaths in March."
      },
      {
        "factor": "Search-and-rescue capacity and regional cooperation",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Better SAR capacity or NGO coordination could avert deaths, reducing risk of hitting 900."
      },
      {
        "factor": "Data lag and potential revisions to Missing Migrants counts",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Early counts are often revised upward; this could push March totals higher than currently observed."
      },
      {
        "factor": "Deterrence and policy crackdown reducing crossing attempts",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stricter controls could reduce crossings, potentially lowering fatalities, though effects are uncertain and may vary by month."
      }
    ],
    "synthesis_rationale": "Anchor at 0.95 with strong evidence from February data; factor updates lean toward modest upward or downward adjustments. The net effect across plausible scenarios yields a posterior around 0.98, with a calibration range 0.93–0.99 to reflect residual uncertainty about March dynamics and data revisions."
  }
}

